import { useEffect, useMemo, useState } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { Link } from 'react-router-dom';
import { AlertTriangle, BarChart3, Calculator, FlaskConical, Play, Save, Upload } from 'lucide-react';
import {
  analyzeScenario, calculateStaffing, cancelSimulationRun, createIssue, createScenario, exportScenario, getSimulationRun, importScenario, listIssues, listScenarios,
  listScenarioVersions, listSimulationRuns, restoreScenarioVersion, runCapacitySweep, runExperiment, runStoredScenario, updateIssue, updateScenario, type AnalyticResult, type CapacitySweepRequest,
  type CapacitySweepResult, type ExperimentRequest, type ExperimentResult, type Scenario, type ScenarioPackage, type SimulationResult, type SimulationRun, type StaffingResult, type StoredScenario,
} from '../api/simulation';
import { emptyScenario, supportOperationsExample } from '../data/simulationExamples';
import { configureScenarioFromBpmn, type ImportSummary } from '../utils/simulationImport';
import { Card, CardHeader, Table, Thead, Th, Tr, Td } from '../components/ui';

type Tab = 'setup'|'results'|'staffing'|'campaigns'|'issues';
const tabLabels:Record<Tab,string> = {setup:'Scenario',results:'Results',staffing:'Capacity planning',campaigns:'Campaigns',issues:'Issues'};
const numeric = (value:string) => Number.isFinite(Number(value)) ? Number(value) : 0;
const durationMean = (d?: {type:string;value?:number;mean?:number;min?:number;max?:number;mode?:number}) => {
  if(!d)return 0;if(d.type==='fixed')return d.value??0;if(d.type==='uniform')return ((d.min??0)+(d.max??0))/2;
  if(d.type==='triangular')return ((d.min??0)+(d.mode??0)+(d.max??0))/3;return d.mean??0;
};
const commaList = (value?:string[]) => value?.join(', ')??'';
const parseCommaList = (value:string) => Array.from(new Set(value.split(',').map(item=>item.trim()).filter(Boolean)));
const parseWeekdays = (value:string) => parseCommaList(value).map(Number).filter(day=>day>=1&&day<=7);
const localDateTime = (value?:string) => value ? value.slice(0,16) : '';

export default function SimulationLab() {
  const queryClient = useQueryClient();
  const [scenario,setScenario] = useState<Scenario>(emptyScenario);
  const [scenarioId,setScenarioId] = useState('');
  const [tab,setTab] = useState<Tab>('setup');
  const [analytic,setAnalytic] = useState<AnalyticResult>();
  const [result,setResult] = useState<SimulationResult>();
  const [busy,setBusy] = useState('');
  const [error,setError] = useState('');
  const [staffingInput,setStaffingInput] = useState({arrivalRatePerHour:1,serviceTimeHours:2,targetWaitingHours:2,maxServers:20});
  const [staffing,setStaffing] = useState<StaffingResult>();
  const [baseline,setBaseline] = useState<SimulationResult>();
  const [activeRunId,setActiveRunId] = useState('');
  const [sweepResult,setSweepResult] = useState<CapacitySweepResult>();
  const [sweepInput,setSweepInput] = useState<CapacitySweepRequest>({resourceId:'',minimumCapacity:1,maximumCapacity:8,step:1,targetMeanCycleMinutes:240});
  const [experimentResult,setExperimentResult] = useState<ExperimentResult>();
  const [experimentInput,setExperimentInput] = useState<ExperimentRequest>({dimensions:[{path:'arrivalRatePerHour',values:[0.5,1,2]}],objective:'mean_cycle'});
  const [importSummary,setImportSummary] = useState<ImportSummary>();
  const [showXml,setShowXml] = useState(false);
  const [selectedVersion,setSelectedVersion] = useState(0);
  const {data:stored=[]} = useQuery({queryKey:['simulation-scenarios'],queryFn:listScenarios,retry:false});
  const {data:versions=[]} = useQuery({queryKey:['simulation-versions',scenarioId],queryFn:()=>listScenarioVersions(scenarioId),enabled:!!scenarioId});
  const {data:runs=[]} = useQuery({queryKey:['simulation-runs',scenarioId],queryFn:()=>listSimulationRuns(scenarioId),enabled:!!scenarioId,refetchInterval:scenarioId?2000:false});
  const {data:activeRun} = useQuery({queryKey:['simulation-run',activeRunId],queryFn:()=>getSimulationRun(activeRunId),enabled:!!activeRunId,refetchInterval:1000});
  const activityRows = useMemo(()=>Object.entries(scenario.activities),[scenario.activities]);
  const flowRows = useMemo(()=>Object.entries(scenario.flows),[scenario.flows]);
  const assignedActivities = useMemo(()=>activityRows.filter(([,activity])=>!!activity.resourceId).length,[activityRows]);

  useEffect(()=>{
    if(!activeRun || !['completed','failed','cancelled'].includes(activeRun.status))return;
    if(activeRun.status==='completed' && activeRun.result){
      if(activeRun.runType==='capacity_sweep')setSweepResult(activeRun.result as CapacitySweepResult);
      else if(activeRun.runType==='experiment')setExperimentResult(activeRun.result as ExperimentResult);
      else setResult(activeRun.result as SimulationResult);
    } else if(activeRun.status==='failed')setError(activeRun.errorMessage??'Simulation failed');
    setActiveRunId('');
    void queryClient.invalidateQueries({queryKey:['simulation-runs',scenarioId]});
    void queryClient.invalidateQueries({queryKey:['simulation-issues',scenarioId]});
  },[activeRun,queryClient,scenarioId]);

  useEffect(()=>{
    if(scenario.resources.some(resource=>resource.id===sweepInput.resourceId))return;
    setSweepInput(current=>({...current,resourceId:scenario.resources[0]?.id??''}));
  },[scenario.resources,sweepInput.resourceId]);

  const execute = async (action:string, fn:()=>Promise<void>) => {
    setBusy(action);setError('');try{await fn()}catch(e:any){setError(e?.response?.data?.message ?? e?.message ?? 'Operation failed')}finally{setBusy('')}
  };
  const patchScenario = (patch:Partial<Scenario>) => setScenario(current=>({...current,...patch}));
  const patchActivity = (id:string,patch:Record<string,unknown>) => setScenario(current=>({...current,activities:{...current.activities,[id]:{...current.activities[id],...patch}}}));
  const setDistributionMean = (id:string,kind:'processingTime'|'waitingTime',value:number) => {
    const old = scenario.activities[id][kind] ?? {type:'fixed' as const,value:0};
    const next = old.type === 'fixed' ? {...old,value}
      : old.type === 'uniform' ? {...old,min:0,max:value*2}
      : old.type === 'triangular' ? {...old,min:0,mode:value,max:value*2}
      : {...old,mean:value};
    patchActivity(id,{[kind]:next});
  };
  const resetWorkspace = () => {
    setScenario(emptyScenario());setScenarioId('');setSelectedVersion(0);setAnalytic(undefined);setResult(undefined);setSweepResult(undefined);setExperimentResult(undefined);setBaseline(undefined);setImportSummary(undefined);setTab('setup');
  };
  const loadExample = () => {
    setScenario(structuredClone(supportOperationsExample));setScenarioId('');setSelectedVersion(0);setAnalytic(undefined);setResult(undefined);setSweepResult(undefined);setExperimentResult(undefined);setImportSummary({processName:'Support operations',activityCount:Object.keys(supportOperationsExample.activities).length,branchFlowCount:Object.keys(supportOperationsExample.flows).length});setTab('setup');
  };
  const importBpmn = async (file:File) => {
    const xml=await file.text();
    const imported=configureScenarioFromBpmn(scenario,xml,file.name.replace(/\.(bpmn|xml)$/i,''));
    setScenario(imported.scenario);setImportSummary(imported.summary);setAnalytic(undefined);setResult(undefined);setSweepResult(undefined);setExperimentResult(undefined);
  };
  const save = async () => {
    const row = scenarioId ? await updateScenario(scenarioId,scenario) : await createScenario(scenario);
    setScenarioId(row.id);setSelectedVersion(row.currentVersion);await queryClient.invalidateQueries({queryKey:['simulation-scenarios']});await queryClient.invalidateQueries({queryKey:['simulation-versions',row.id]});return row.id;
  };
  const applyStoredScenario = (row:StoredScenario) => {
    setScenarioId(row.id);setScenario({...row.configuration,name:row.name,bpmnXml:row.bpmnXml});setSelectedVersion(row.currentVersion);setAnalytic(undefined);setResult(undefined);setSweepResult(undefined);setExperimentResult(undefined);setImportSummary(undefined);
  };
  const loadStored = (id:string) => {
    const row=stored.find(item=>item.id===id);if(!row)return;
    applyStoredScenario(row);
  };
  const downloadScenario = async () => {
    if(!scenarioId)return;
    const pkg=await exportScenario(scenarioId);const blob=new Blob([JSON.stringify(pkg,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=`${scenario.name.replace(/[^a-z0-9-_]+/gi,'-').toLowerCase()||'scenario'}.simulation.json`;anchor.click();URL.revokeObjectURL(url);
  };
  const uploadScenario = async (file:File) => {
    const pkg=JSON.parse(await file.text()) as ScenarioPackage;const row=await importScenario(pkg);applyStoredScenario(row);await queryClient.invalidateQueries({queryKey:['simulation-scenarios']});
  };

  return <div className="p-6 space-y-5">
    <div className="flex flex-wrap items-center justify-between gap-3">
      <div><h1 className="text-xl font-bold text-gray-900 flex items-center gap-2"><FlaskConical className="w-5 h-5 text-blue-600"/>Simulation studio</h1><p className="text-sm text-gray-500 mt-0.5">Build reusable process scenarios, run experiments, compare capacity, and validate redesign decisions.</p></div>
      <div className="flex flex-wrap gap-2">
        <Link to="/modeler" className="px-3 py-2 text-sm border rounded-lg bg-white">Open modeler</Link>
        <select value={scenarioId} onChange={e=>e.target.value?loadStored(e.target.value):resetWorkspace()} className="border border-gray-200 rounded-lg px-3 py-2 text-sm bg-white"><option value="">Unsaved scenario</option>{stored.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select>
        {scenarioId&&<><select value={selectedVersion||stored.find(item=>item.id===scenarioId)?.currentVersion||0} onChange={e=>setSelectedVersion(Number(e.target.value))} className="border border-gray-200 rounded-lg px-3 py-2 text-sm bg-white">{versions.map(version=><option key={version.id} value={version.version}>Version {version.version} · {new Date(version.createdAt).toLocaleString()}</option>)}</select><button disabled={!selectedVersion||selectedVersion===stored.find(item=>item.id===scenarioId)?.currentVersion} onClick={()=>execute('restore',async()=>{const row=await restoreScenarioVersion(scenarioId,selectedVersion);applyStoredScenario(row);await queryClient.invalidateQueries({queryKey:['simulation-scenarios']});await queryClient.invalidateQueries({queryKey:['simulation-versions',scenarioId]})})} className="px-3 py-2 text-sm border rounded-lg bg-white disabled:opacity-50">Restore version</button><button onClick={()=>execute('export',downloadScenario)} className="px-3 py-2 text-sm border rounded-lg bg-white">Export</button></>}
        <label className="px-3 py-2 text-sm border rounded-lg bg-white cursor-pointer">Import<input type="file" accept=".json" className="hidden" onChange={async e=>{const file=e.target.files?.[0];if(file)await execute('import-package',()=>uploadScenario(file))}}/></label>
        <button onClick={resetWorkspace} className="px-3 py-2 text-sm border rounded-lg bg-white">New scenario</button>
        <button onClick={loadExample} className="px-3 py-2 text-sm border rounded-lg bg-white">Load support example</button>
      </div>
    </div>
    <div className="flex overflow-x-auto border-b border-gray-200">{(['setup','results','staffing','campaigns','issues'] as Tab[]).map(value=><button key={value} onClick={()=>setTab(value)} className={`px-4 py-2 text-sm whitespace-nowrap border-b-2 ${tab===value?'border-blue-600 text-blue-600':'border-transparent text-gray-500'}`}>{tabLabels[value]}</button>)}</div>
    {error&&<div className="rounded-lg bg-red-50 border border-red-200 text-red-700 text-sm px-4 py-3">{error}</div>}
    {activeRun&&<div className="rounded-lg bg-blue-50 border border-blue-200 text-blue-800 text-sm px-4 py-3 flex items-center justify-between"><span>{activeRun.runType==='capacity_sweep'?'Capacity sweep':activeRun.runType==='experiment'?'Multi-parameter experiment':'Simulation'}: {activeRun.status} — {activeRun.progress}%</span><button onClick={async()=>{await cancelSimulationRun(activeRun.id);setActiveRunId('')}} className="text-xs font-medium">Cancel</button></div>}

    {tab==='setup'&&<div className="space-y-5">
      {!scenario.bpmnXml&&<Card className="border-blue-200 bg-blue-50"><div className="p-6"><h2 className="font-semibold text-blue-950">Start with any BPMN process</h2><p className="text-sm text-blue-800 mt-1">Import a BPMN 2.0 file below. Activities and decision branches will be discovered and initialized automatically; then add resources and replace the default assumptions with observed data.</p></div></Card>}
      <Card><CardHeader title="Scenario configuration" subtitle="Define the experiment horizon, reproducibility, and calendar origin."/><div className="p-6 pt-2 grid sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7 gap-4">
        <Field label="Name"><input value={scenario.name} onChange={e=>patchScenario({name:e.target.value})} className="input"/></Field>
        <NumberField label="Arrival rate / hour" value={scenario.arrivalRatePerHour} onChange={v=>patchScenario({arrivalRatePerHour:v})}/>
        <NumberField label="Duration (hours)" value={scenario.durationHours} onChange={v=>patchScenario({durationHours:v})}/>
        <NumberField label="Arrival cap (0 = duration)" value={scenario.maxArrivals??0} onChange={v=>patchScenario({maxArrivals:Math.max(0,v)})}/>
        <NumberField label="Replications" value={scenario.replications} onChange={v=>patchScenario({replications:Math.max(1,v)})}/>
        <NumberField label="Random seed" value={scenario.seed} onChange={v=>patchScenario({seed:v})}/>
        <Field label="Start time"><input type="datetime-local" value={localDateTime(scenario.startTime)} onChange={e=>patchScenario({startTime:e.target.value?new Date(e.target.value).toISOString():undefined})} className="input"/></Field>
      </div></Card>
      <ArrivalEditor scenario={scenario} patchScenario={patchScenario}/>
      <Card><CardHeader title="Process model" subtitle="Import or replace a BPMN 2.0 model; matching parameter values are preserved across model revisions."/><div className="p-6 pt-2 space-y-3"><div className="flex flex-wrap items-center gap-2"><label className="inline-flex items-center gap-2 px-3 py-2 border rounded-lg text-sm cursor-pointer bg-white"><Upload className="w-4 h-4"/>{scenario.bpmnXml?'Replace BPMN':'Import BPMN'}<input type="file" accept=".bpmn,.xml" className="hidden" onChange={async e=>{const f=e.target.files?.[0];if(f)await execute('import',()=>importBpmn(f))}}/></label>{scenario.bpmnXml&&<button onClick={()=>setShowXml(value=>!value)} className="px-3 py-2 text-sm border rounded-lg bg-white">{showXml?'Hide XML':'View XML'}</button>}{scenario.bpmnXml&&<span className="text-xs text-gray-500">{activityRows.length} activities · {flowRows.length} branch flows · {assignedActivities} resource assignments</span>}</div>{importSummary&&<div className="rounded-lg bg-emerald-50 border border-emerald-200 px-3 py-2 text-sm text-emerald-800">Imported {importSummary.processName?`“${importSummary.processName}”`: 'process'}: {importSummary.activityCount} activities and {importSummary.branchFlowCount} configurable branch flows detected.</div>}{showXml&&<textarea value={scenario.bpmnXml} onChange={e=>patchScenario({bpmnXml:e.target.value})} className="w-full h-56 font-mono text-xs border border-gray-200 rounded-lg p-3"/>}</div></Card>
      <CalendarEditor scenario={scenario} patchScenario={patchScenario}/>
      <Card><CardHeader title="Resources and skills" subtitle="Attach working calendars, declare skills, and define the maximum concurrent capacity."/><div className="overflow-x-auto"><Table><Thead><tr><Th>ID</Th><Th>Name</Th><Th>Capacity</Th><Th>Cost / hour</Th><Th>Calendar</Th><Th>Skills</Th><Th></Th></tr></Thead><tbody>{scenario.resources.map((r,index)=><Tr key={r.id}><Td>{r.id}</Td><Td><input value={r.name} onChange={e=>patchScenario({resources:scenario.resources.map((x,i)=>i===index?{...x,name:e.target.value}:x)})} className="table-input"/></Td><Td><input type="number" min="1" value={r.capacity} onChange={e=>patchScenario({resources:scenario.resources.map((x,i)=>i===index?{...x,capacity:Math.max(1,numeric(e.target.value))}:x)})} className="table-input w-20"/></Td><Td><input type="number" min="0" value={r.costPerHour} onChange={e=>patchScenario({resources:scenario.resources.map((x,i)=>i===index?{...x,costPerHour:Math.max(0,numeric(e.target.value))}:x)})} className="table-input w-24"/></Td><Td><select value={r.calendarId??''} onChange={e=>patchScenario({resources:scenario.resources.map((x,i)=>i===index?{...x,calendarId:e.target.value||undefined}:x)})} className="table-input"><option value="">Always available</option>{(scenario.calendars??[]).map(calendar=><option key={calendar.id} value={calendar.id}>{calendar.name||calendar.id}</option>)}</select></Td><Td><input value={commaList(r.skills)} onChange={e=>patchScenario({resources:scenario.resources.map((x,i)=>i===index?{...x,skills:parseCommaList(e.target.value)}:x)})} placeholder="review, legal" className="table-input min-w-36"/></Td><Td><button onClick={()=>patchScenario({resources:scenario.resources.filter((_,i)=>i!==index)})} className="text-xs text-red-600">Remove</button></Td></Tr>)}</tbody></Table></div><div className="p-4 border-t"><button onClick={()=>{const id=window.prompt('Resource ID');if(id&&!scenario.resources.some(r=>r.id===id))patchScenario({resources:[...scenario.resources,{id,name:id,capacity:1,costPerHour:0,skills:[]}]})}} className="text-sm text-blue-600">+ Add resource</button></div></Card>
      <Card><CardHeader title="Activity parameters and routing" subtitle="Configure duration, eligible resources, required skills, routing strategy, and queue priority."/>{activityRows.length===0?<p className="p-6 pt-2 text-sm text-gray-500">Import a BPMN model to discover its activities.</p>:<div className="overflow-x-auto"><Table><Thead><tr><Th>BPMN element ID</Th><Th>Distribution</Th><Th>Processing mean</Th><Th>Std dev</Th><Th>Explicit wait</Th><Th>Primary resource</Th><Th>Eligible resources</Th><Th>Required skills</Th><Th>Routing</Th><Th>Priority</Th><Th>Value added</Th><Th></Th></tr></Thead><tbody>{activityRows.map(([id,a])=><Tr key={id}><Td><code className="text-xs">{id}</code></Td><Td><select value={a.processingTime.type} onChange={e=>patchActivity(id,{processingTime:{type:e.target.value,value:durationMean(a.processingTime),mean:durationMean(a.processingTime),standardDeviation:a.processingTime.standardDeviation??0}})} className="table-input"><option value="fixed">Fixed</option><option value="normal">Normal</option><option value="exponential">Exponential</option><option value="uniform">Uniform</option><option value="triangular">Triangular</option></select></Td><Td><input type="number" value={durationMean(a.processingTime)} onChange={e=>setDistributionMean(id,'processingTime',numeric(e.target.value))} className="table-input w-24"/></Td><Td><input type="number" disabled={a.processingTime.type!=='normal'} value={a.processingTime.standardDeviation??0} onChange={e=>patchActivity(id,{processingTime:{...a.processingTime,standardDeviation:numeric(e.target.value)}})} className="table-input w-20 disabled:bg-gray-100"/></Td><Td><input type="number" value={durationMean(a.waitingTime)} onChange={e=>setDistributionMean(id,'waitingTime',numeric(e.target.value))} className="table-input w-24"/></Td><Td><select value={a.resourceId??''} onChange={e=>patchActivity(id,{resourceId:e.target.value||undefined})} className="table-input"><option value="">None / skill pool</option>{scenario.resources.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select></Td><Td><input value={commaList(a.resourceIds)} onChange={e=>patchActivity(id,{resourceIds:parseCommaList(e.target.value)})} placeholder="team-a, team-b" className="table-input min-w-36"/></Td><Td><input value={commaList(a.requiredSkills)} onChange={e=>patchActivity(id,{requiredSkills:parseCommaList(e.target.value)})} placeholder="legal, french" className="table-input min-w-36"/></Td><Td><select value={a.routingRule??'least_queue'} onChange={e=>patchActivity(id,{routingRule:e.target.value})} className="table-input"><option value="least_queue">Least queue</option><option value="round_robin">Round robin</option><option value="fixed">Fixed</option></select></Td><Td><input type="number" value={a.priority??0} onChange={e=>patchActivity(id,{priority:numeric(e.target.value)})} className="table-input w-20"/></Td><Td><input type="checkbox" checked={a.valueAdded} onChange={e=>patchActivity(id,{valueAdded:e.target.checked})}/></Td><Td><button onClick={()=>setScenario(current=>{const activities={...current.activities};delete activities[id];return {...current,activities}})} className="text-xs text-red-600">Remove</button></Td></Tr>)}</tbody></Table></div>}<div className="p-4 border-t"><button onClick={()=>{const id=window.prompt('BPMN activity element ID');if(id&&!scenario.activities[id])patchScenario({activities:{...scenario.activities,[id]:{processingTime:{type:'fixed',value:0},waitingTime:{type:'fixed',value:0},valueAdded:true}}})}} className="text-sm text-blue-600">+ Add activity manually</button></div></Card>
      <Card><CardHeader title="Branch probabilities" subtitle="Exclusive flows total 100%; inclusive probabilities are independent; parallel flows need no probability."/><div className="p-6 pt-2 grid sm:grid-cols-2 lg:grid-cols-4 gap-3">{flowRows.map(([id,p])=><div key={id} className="flex gap-1 items-end"><Field label={id}><input type="number" step="0.01" min="0" max="1" value={p.probability} onChange={e=>patchScenario({flows:{...scenario.flows,[id]:{probability:numeric(e.target.value)}}})} className="input"/></Field><button onClick={()=>setScenario(current=>{const flows={...current.flows};delete flows[id];return {...current,flows}})} className="px-2 py-2 text-xs text-red-600">×</button></div>)}</div><div className="px-6 pb-4"><button onClick={()=>{const id=window.prompt('BPMN sequence-flow ID');if(id&&!scenario.flows[id])patchScenario({flows:{...scenario.flows,[id]:{probability:0}}})}} className="text-sm text-blue-600">+ Add flow probability</button></div></Card>
      <div className="flex justify-end gap-2"><button disabled={!!busy||!scenario.bpmnXml} onClick={()=>execute('analyze',async()=>{setAnalytic(await analyzeScenario(scenario));setTab('results')})} className="px-4 py-2 border rounded-lg text-sm bg-white disabled:opacity-50"><BarChart3 className="inline w-4 h-4 mr-2"/>Analyze</button><button disabled={!!busy||!scenario.bpmnXml} onClick={()=>execute('save',async()=>{await save()})} className="px-4 py-2 border rounded-lg text-sm bg-white disabled:opacity-50"><Save className="inline w-4 h-4 mr-2"/>Save scenario</button><button disabled={!!busy||!!activeRunId||!scenario.bpmnXml} onClick={()=>execute('run',async()=>{const id=await save();const run=await runStoredScenario(id);setActiveRunId(run.id);setTab('campaigns')})} className="px-4 py-2 rounded-lg text-sm bg-blue-600 disabled:bg-blue-300 text-white"><Play className="inline w-4 h-4 mr-2"/>{busy==='run'?'Queuing…':'Run experiment'}</button></div>
    </div>}

    {tab==='results'&&<><Results analytic={result?.analytic??analytic} result={result} baseline={baseline}/>{result&&<div className="flex justify-end gap-2"><button onClick={()=>setBaseline(result)} className="px-3 py-2 text-sm border rounded-lg bg-white">Use as as-is baseline</button><button onClick={()=>{setScenario(current=>({...structuredClone(current),name:`${current.name} — to-be`}));setScenarioId('');setResult(undefined);setTab('setup')}} className="px-3 py-2 text-sm bg-blue-600 text-white rounded-lg">Duplicate as to-be</button></div>}</>}
    {tab==='staffing'&&<div className="grid lg:grid-cols-3 gap-5"><Card className="lg:col-span-1"><CardHeader title="Erlang-C staffing" subtitle="M/M/c estimate for a shared work queue."/><div className="p-6 pt-2 space-y-4"><NumberField label="Arrival rate / hour" value={staffingInput.arrivalRatePerHour} onChange={v=>setStaffingInput({...staffingInput,arrivalRatePerHour:v})}/><NumberField label="Mean service time (hours)" value={staffingInput.serviceTimeHours} onChange={v=>setStaffingInput({...staffingInput,serviceTimeHours:v})}/><NumberField label="Target mean wait (hours)" value={staffingInput.targetWaitingHours} onChange={v=>setStaffingInput({...staffingInput,targetWaitingHours:v})}/><NumberField label="Maximum servers" value={staffingInput.maxServers} onChange={v=>setStaffingInput({...staffingInput,maxServers:v})}/><button onClick={()=>execute('staffing',async()=>setStaffing(await calculateStaffing(staffingInput)))} className="w-full px-4 py-2 rounded-lg bg-blue-600 text-white text-sm"><Calculator className="inline w-4 h-4 mr-2"/>Calculate minimum</button></div></Card><Card className="lg:col-span-2"><CardHeader title={staffing?`Minimum: ${staffing.minimumServers} servers`:'Staffing curve'} subtitle="Unstable configurations have utilization ≥ 100%."/>{staffing&&<Table><Thead><tr><Th>Servers</Th><Th>Utilization</Th><Th>P(wait)</Th><Th>Mean wait</Th><Th>Target</Th></tr></Thead><tbody>{staffing.points.map(p=><Tr key={p.servers}><Td>{p.servers}</Td><Td>{(p.utilization*100).toFixed(1)}%</Td><Td>{p.stable?`${(p.probabilityOfWait*100).toFixed(1)}%`:'—'}</Td><Td>{p.stable?`${p.meanWaitingHours.toFixed(2)} h`:'Unstable'}</Td><Td>{p.meetsTarget?'✓':'—'}</Td></Tr>)}</tbody></Table>}</Card></div>}
    {tab==='campaigns'&&<Campaigns scenario={scenario} input={sweepInput} setInput={setSweepInput} experimentInput={experimentInput} setExperimentInput={setExperimentInput} runs={runs} result={sweepResult} experimentResult={experimentResult} disabled={!!activeRunId||!!busy} onStart={()=>execute('sweep',async()=>{const id=await save();const run=await runCapacitySweep(id,sweepInput);setActiveRunId(run.id)})} onStartExperiment={()=>execute('experiment',async()=>{const id=await save();const run=await runExperiment(id,experimentInput);setActiveRunId(run.id)})} onOpen={run=>{if(run.runType==='capacity_sweep')setSweepResult(run.result as CapacitySweepResult);else if(run.runType==='experiment')setExperimentResult(run.result as ExperimentResult);else{setResult(run.result as SimulationResult);setTab('results')}}} onTrack={run=>setActiveRunId(run.id)} onCancel={async run=>{await cancelSimulationRun(run.id);await queryClient.invalidateQueries({queryKey:['simulation-runs',scenarioId]})}}/>}
    {tab==='issues'&&<Issues result={result} scenarioId={scenarioId}/>}
  </div>;
}

function ArrivalEditor({scenario,patchScenario}:{scenario:Scenario;patchScenario:(patch:Partial<Scenario>)=>void}) {
  const pattern=scenario.arrivalPattern;
  const type=pattern?.type??'poisson';
  const update=(patch:Partial<NonNullable<Scenario['arrivalPattern']>>) => patchScenario({arrivalPattern:{type,...pattern,...patch} as NonNullable<Scenario['arrivalPattern']>});
  const changeType=(next:NonNullable<Scenario['arrivalPattern']>['type']) => {
    if(next==='poisson'){patchScenario({arrivalPattern:undefined});return}
    if(next==='piecewise_poisson')patchScenario({arrivalPattern:{type:next,segments:[{startMinute:0,endMinute:480,ratePerHour:scenario.arrivalRatePerHour}]}});
    if(next==='scheduled')patchScenario({arrivalPattern:{type:next,scheduledMinutes:[0]}});
    if(next==='batch_poisson')patchScenario({arrivalPattern:{type:next,ratePerHour:scenario.arrivalRatePerHour,batchSize:2}});
  };
  return <Card><CardHeader title="Demand pattern" subtitle="Model constant, time-varying, scheduled, or batched arrivals."/><div className="p-6 pt-2 space-y-4">
    <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4"><Field label="Arrival model"><select value={type} onChange={e=>changeType(e.target.value as NonNullable<Scenario['arrivalPattern']>['type'])} className="input"><option value="poisson">Constant Poisson</option><option value="piecewise_poisson">Time-varying Poisson</option><option value="scheduled">Scheduled arrivals</option><option value="batch_poisson">Batch Poisson</option></select></Field>{type==='batch_poisson'&&<><NumberField label="Batch arrival rate / hour" value={pattern?.ratePerHour??scenario.arrivalRatePerHour} onChange={value=>update({ratePerHour:value})}/><NumberField label="Cases per batch" value={pattern?.batchSize??2} onChange={value=>update({batchSize:Math.max(1,value)})}/></>}</div>
    {type==='piecewise_poisson'&&<><Table><Thead><tr><Th>Start minute</Th><Th>End minute</Th><Th>Rate / hour</Th><Th></Th></tr></Thead><tbody>{(pattern?.segments??[]).map((segment,index)=><Tr key={index}><Td><input type="number" min="0" value={segment.startMinute} onChange={e=>update({segments:pattern?.segments?.map((item,i)=>i===index?{...item,startMinute:numeric(e.target.value)}:item)})} className="table-input"/></Td><Td><input type="number" min="0" value={segment.endMinute} onChange={e=>update({segments:pattern?.segments?.map((item,i)=>i===index?{...item,endMinute:numeric(e.target.value)}:item)})} className="table-input"/></Td><Td><input type="number" min="0" value={segment.ratePerHour} onChange={e=>update({segments:pattern?.segments?.map((item,i)=>i===index?{...item,ratePerHour:numeric(e.target.value)}:item)})} className="table-input"/></Td><Td><button onClick={()=>update({segments:pattern?.segments?.filter((_,i)=>i!==index)})} className="text-xs text-red-600">Remove</button></Td></Tr>)}</tbody></Table><button onClick={()=>update({segments:[...(pattern?.segments??[]),{startMinute:0,endMinute:60,ratePerHour:scenario.arrivalRatePerHour}]})} className="text-sm text-blue-600">+ Add demand interval</button></>}
    {type==='scheduled'&&<Field label="Arrival minutes from scenario start (comma separated)"><textarea value={(pattern?.scheduledMinutes??[]).join(', ')} onChange={e=>update({scheduledMinutes:parseCommaList(e.target.value).map(Number).filter(value=>Number.isFinite(value)&&value>=0)})} className="input h-20" placeholder="0, 15, 60, 120"/></Field>}
  </div></Card>;
}

function CalendarEditor({scenario,patchScenario}:{scenario:Scenario;patchScenario:(patch:Partial<Scenario>)=>void}) {
  const calendars=scenario.calendars??[];
  const update=(index:number,patch:Partial<(typeof calendars)[number]>)=>patchScenario({calendars:calendars.map((calendar,i)=>i===index?{...calendar,...patch}:calendar)});
  return <Card><CardHeader title="Business calendars and shifts" subtitle="ISO weekdays: 1 is Monday and 7 is Sunday. Exception dates with no shifts are unavailable holidays."/><div className="p-6 pt-2 space-y-5">
    {calendars.length===0&&<p className="text-sm text-gray-500">No calendar: resources are available continuously.</p>}
    {calendars.map((calendar,index)=><div key={calendar.id} className="border border-gray-200 rounded-lg p-4 space-y-3"><div className="grid sm:grid-cols-3 gap-3"><Field label="Calendar ID"><input value={calendar.id} disabled className="input bg-gray-50"/></Field><Field label="Name"><input value={calendar.name} onChange={e=>update(index,{name:e.target.value})} className="input"/></Field><Field label="IANA timezone"><input value={calendar.timezone} onChange={e=>update(index,{timezone:e.target.value})} placeholder="Europe/Brussels" className="input"/></Field></div>
      <Table><Thead><tr><Th>Weekdays</Th><Th>Start minute</Th><Th>End minute</Th><Th>Capacity (0 = resource)</Th><Th></Th></tr></Thead><tbody>{calendar.shifts.map((shift,shiftIndex)=><Tr key={shiftIndex}><Td><input value={commaList(shift.weekdays?.map(String))} onChange={e=>update(index,{shifts:calendar.shifts.map((item,i)=>i===shiftIndex?{...item,weekdays:parseWeekdays(e.target.value)}:item)})} className="table-input" placeholder="1,2,3,4,5"/></Td><Td><input type="number" min="0" max="1439" value={shift.startMinute} onChange={e=>update(index,{shifts:calendar.shifts.map((item,i)=>i===shiftIndex?{...item,startMinute:numeric(e.target.value)}:item)})} className="table-input"/></Td><Td><input type="number" min="1" max="1440" value={shift.endMinute} onChange={e=>update(index,{shifts:calendar.shifts.map((item,i)=>i===shiftIndex?{...item,endMinute:numeric(e.target.value)}:item)})} className="table-input"/></Td><Td><input type="number" min="0" value={shift.capacity??0} onChange={e=>update(index,{shifts:calendar.shifts.map((item,i)=>i===shiftIndex?{...item,capacity:Math.max(0,numeric(e.target.value))}:item)})} className="table-input"/></Td><Td><button onClick={()=>update(index,{shifts:calendar.shifts.filter((_,i)=>i!==shiftIndex)})} className="text-xs text-red-600">Remove</button></Td></Tr>)}</tbody></Table>
      <div className="flex flex-wrap items-center gap-3"><button onClick={()=>update(index,{shifts:[...calendar.shifts,{weekdays:[1,2,3,4,5],startMinute:540,endMinute:1020,capacity:0}]})} className="text-sm text-blue-600">+ Add shift</button><button onClick={()=>{const date=window.prompt('Unavailable date (YYYY-MM-DD)');if(date&&!calendar.exceptions?.some(item=>item.date===date))update(index,{exceptions:[...(calendar.exceptions??[]),{date,shifts:[]}]})}} className="text-sm text-blue-600">+ Add holiday</button>{calendar.exceptions?.map(exception=><span key={exception.date} className="inline-flex items-center gap-1 rounded-full bg-gray-100 px-2 py-1 text-xs">{exception.date}<button onClick={()=>update(index,{exceptions:calendar.exceptions?.filter(item=>item.date!==exception.date)})} className="text-red-600">×</button></span>)}<button onClick={()=>patchScenario({calendars:calendars.filter((_,i)=>i!==index),resources:scenario.resources.map(resource=>resource.calendarId===calendar.id?{...resource,calendarId:undefined}:resource)})} className="ml-auto text-sm text-red-600">Remove calendar</button></div>
    </div>)}
    <button onClick={()=>{const id=window.prompt('Calendar ID');if(id&&!calendars.some(calendar=>calendar.id===id))patchScenario({calendars:[...calendars,{id,name:id,timezone:'UTC',shifts:[{weekdays:[1,2,3,4,5],startMinute:540,endMinute:1020,capacity:0}]}]})}} className="text-sm text-blue-600">+ Add business calendar</button>
  </div></Card>;
}

function Campaigns({scenario,input,setInput,experimentInput,setExperimentInput,runs,result,experimentResult,disabled,onStart,onStartExperiment,onOpen,onTrack,onCancel}:{
  scenario:Scenario;input:CapacitySweepRequest;setInput:(value:CapacitySweepRequest)=>void;experimentInput:ExperimentRequest;setExperimentInput:(value:ExperimentRequest)=>void;runs:SimulationRun[];
  result?:CapacitySweepResult;experimentResult?:ExperimentResult;disabled:boolean;onStart:()=>void;onStartExperiment:()=>void;onOpen:(run:SimulationRun)=>void;onTrack:(run:SimulationRun)=>void;onCancel:(run:SimulationRun)=>void;
}) {
  const suggestedPaths=['arrivalRatePerHour','durationHours','maxArrivals',...(scenario.arrivalPattern?[`arrivalPattern.ratePerHour`,`arrivalPattern.batchSize`]:[]),...scenario.resources.flatMap(resource=>[`resource.${resource.id}.capacity`,`resource.${resource.id}.costPerHour`]),...Object.keys(scenario.activities).flatMap(id=>[`activity.${id}.processingTime.value`,`activity.${id}.processingTime.mean`,`activity.${id}.waitingTime.value`,`activity.${id}.waitingTime.mean`,`activity.${id}.priority`]),...Object.keys(scenario.flows).map(id=>`flow.${id}.probability`)];
  const simulationRuns=runs.filter(run=>run.runType==='simulation'&&run.status==='completed'&&run.result) as Array<SimulationRun&{result:SimulationResult}>;
  const [compareA,setCompareA]=useState('');
  const [compareB,setCompareB]=useState('');
  const comparisonA=simulationRuns.find(run=>run.id===compareA);
  const comparisonB=simulationRuns.find(run=>run.id===compareB);
  return <div className="space-y-5">
    <div className="grid lg:grid-cols-3 gap-5">
      <Card><CardHeader title="Capacity sweep" subtitle="Run the same seeded experiment for every capacity."/><div className="p-6 pt-2 space-y-4">
        <Field label="Resource"><select value={input.resourceId} onChange={e=>setInput({...input,resourceId:e.target.value})} className="input">{scenario.resources.map(resource=><option key={resource.id} value={resource.id}>{resource.name}</option>)}</select></Field>
        <NumberField label="Minimum capacity" value={input.minimumCapacity} onChange={value=>setInput({...input,minimumCapacity:value})}/>
        <NumberField label="Maximum capacity" value={input.maximumCapacity} onChange={value=>setInput({...input,maximumCapacity:value})}/>
        <NumberField label="Step" value={input.step} onChange={value=>setInput({...input,step:value})}/>
        <NumberField label="Target mean cycle (minutes)" value={input.targetMeanCycleMinutes??0} onChange={value=>setInput({...input,targetMeanCycleMinutes:value})}/>
        <NumberField label="Target p95 cycle (minutes)" value={input.targetP95CycleMinutes??0} onChange={value=>setInput({...input,targetP95CycleMinutes:value})}/>
        <button disabled={disabled||!input.resourceId} onClick={onStart} className="w-full px-4 py-2 rounded-lg bg-blue-600 disabled:bg-blue-300 text-white text-sm">Start asynchronous sweep</button>
      </div></Card>
      <Card className="lg:col-span-2"><CardHeader title={result?.recommendedCapacity?`Recommended capacity: ${result.recommendedCapacity}`:'Capacity comparison'} subtitle="The first capacity meeting all non-zero targets is recommended."/>{result?<Table><Thead><tr><Th>Capacity</Th><Th>Mean cycle</Th><Th>p95</Th><Th>Throughput</Th><Th>Utilization</Th><Th>Mean cost</Th><Th>Target</Th></tr></Thead><tbody>{result.points.map(point=><Tr key={point.capacity}><Td>{point.capacity}</Td><Td>{point.meanCycleMinutes.toFixed(1)} min</Td><Td>{point.p95CycleMinutes.toFixed(1)} min</Td><Td>{point.throughputPerHour.toFixed(2)}/h</Td><Td>{(point.utilization*100).toFixed(1)}%</Td><Td>{point.meanCost.toFixed(2)}</Td><Td>{point.meetsTarget?'✓':'—'}</Td></Tr>)}</tbody></Table>:<p className="p-8 text-sm text-gray-500 text-center">Launch a sweep or open a completed campaign.</p>}</Card>
    </div>
    <div className="grid lg:grid-cols-3 gap-5"><Card><CardHeader title="Multi-parameter experiment" subtitle="Run a full-factorial design with up to 256 combinations."/><div className="p-6 pt-2 space-y-4"><Field label="Optimization objective"><select value={experimentInput.objective??'mean_cycle'} onChange={e=>setExperimentInput({...experimentInput,objective:e.target.value as ExperimentRequest['objective']})} className="input"><option value="mean_cycle">Minimize mean cycle</option><option value="p95_cycle">Minimize p95 cycle</option><option value="cost">Minimize mean cost</option><option value="throughput">Maximize throughput</option></select></Field>{experimentInput.dimensions.map((dimension,index)=><div key={index} className="border rounded-lg p-3 space-y-2"><Field label={`Parameter ${index+1}`}><input list="experiment-paths" value={dimension.path} onChange={e=>setExperimentInput({...experimentInput,dimensions:experimentInput.dimensions.map((item,i)=>i===index?{...item,path:e.target.value}:item)})} className="input"/></Field><Field label="Values (comma separated)"><input value={dimension.values.join(', ')} onChange={e=>setExperimentInput({...experimentInput,dimensions:experimentInput.dimensions.map((item,i)=>i===index?{...item,values:parseCommaList(e.target.value).map(Number).filter(Number.isFinite)}:item)})} className="input"/></Field><button onClick={()=>setExperimentInput({...experimentInput,dimensions:experimentInput.dimensions.filter((_,i)=>i!==index)})} className="text-xs text-red-600">Remove dimension</button></div>)}<datalist id="experiment-paths">{suggestedPaths.map(path=><option key={path} value={path}/>)}</datalist><button onClick={()=>setExperimentInput({...experimentInput,dimensions:[...experimentInput.dimensions,{path:suggestedPaths[0]??'arrivalRatePerHour',values:[1,2]}]})} className="text-sm text-blue-600">+ Add dimension</button><div className="grid grid-cols-2 gap-3"><NumberField label="Max mean cycle" value={experimentInput.targetMeanCycleMinutes??0} onChange={value=>setExperimentInput({...experimentInput,targetMeanCycleMinutes:value})}/><NumberField label="Max p95 cycle" value={experimentInput.targetP95CycleMinutes??0} onChange={value=>setExperimentInput({...experimentInput,targetP95CycleMinutes:value})}/><NumberField label="Max mean cost" value={experimentInput.maximumMeanCost??0} onChange={value=>setExperimentInput({...experimentInput,maximumMeanCost:value})}/><NumberField label="Min throughput" value={experimentInput.minimumThroughput??0} onChange={value=>setExperimentInput({...experimentInput,minimumThroughput:value})}/></div><button disabled={disabled||experimentInput.dimensions.length===0||experimentInput.dimensions.some(d=>!d.path||d.values.length===0)} onClick={onStartExperiment} className="w-full px-4 py-2 rounded-lg bg-blue-600 disabled:bg-blue-300 text-white text-sm">Run factorial experiment</button></div></Card><Card className="lg:col-span-2"><CardHeader title={experimentResult?.recommendedPoint!=null?`Recommended combination #${experimentResult.recommendedPoint+1}`:'Experiment comparison'} subtitle="The best feasible point is selected using the configured objective."/>{experimentResult?<div className="overflow-x-auto"><Table><Thead><tr><Th>#</Th><Th>Parameters</Th><Th>Mean cycle</Th><Th>p95</Th><Th>Throughput</Th><Th>Cost</Th><Th>Feasible</Th></tr></Thead><tbody>{experimentResult.points.map((point,index)=><Tr key={index}><Td>{index+1}{experimentResult.recommendedPoint===index?' ★':''}</Td><Td><code className="text-xs whitespace-nowrap">{Object.entries(point.parameters).map(([path,value])=>`${path}=${value}`).join(', ')}</code>{point.error&&<p className="text-xs text-red-600">{point.error}</p>}</Td><Td>{point.error?'—':point.meanCycleMinutes.toFixed(1)}</Td><Td>{point.error?'—':point.p95CycleMinutes.toFixed(1)}</Td><Td>{point.error?'—':point.throughputPerHour.toFixed(2)}</Td><Td>{point.error?'—':point.meanCost.toFixed(2)}</Td><Td>{point.meetsConstraints?'✓':'—'}</Td></Tr>)}</tbody></Table></div>:<p className="p-8 text-sm text-gray-500 text-center">Configure two or more parameters to explore process-design tradeoffs.</p>}</Card></div>
    <Card><CardHeader title="Run comparison dashboard" subtitle="Compare two completed simulation campaigns of this scenario."/><div className="p-6 pt-2 space-y-4"><div className="grid sm:grid-cols-2 gap-4"><Field label="Baseline run"><select value={compareA} onChange={e=>setCompareA(e.target.value)} className="input"><option value="">Select a run</option>{simulationRuns.map(run=><option key={run.id} value={run.id}>{new Date(run.completedAt??run.startedAt).toLocaleString()}</option>)}</select></Field><Field label="Comparison run"><select value={compareB} onChange={e=>setCompareB(e.target.value)} className="input"><option value="">Select a run</option>{simulationRuns.map(run=><option key={run.id} value={run.id}>{new Date(run.completedAt??run.startedAt).toLocaleString()}</option>)}</select></Field></div>{comparisonA&&comparisonB?<Table><Thead><tr><Th>Metric</Th><Th>Baseline</Th><Th>Comparison</Th><Th>Change</Th></tr></Thead><tbody>{[['Mean cycle',comparisonA.result.metrics.meanCycleMinutes,comparisonB.result.metrics.meanCycleMinutes],['p95 cycle',comparisonA.result.metrics.p95CycleMinutes,comparisonB.result.metrics.p95CycleMinutes],['Throughput / hour',comparisonA.result.metrics.throughputPerHour,comparisonB.result.metrics.throughputPerHour],['Mean cost',comparisonA.result.metrics.meanCost,comparisonB.result.metrics.meanCost],['Cycle efficiency (%)',comparisonA.result.metrics.cycleTimeEfficiency*100,comparisonB.result.metrics.cycleTimeEfficiency*100]].map(([label,left,right])=><Tr key={String(label)}><Td>{label}</Td><Td>{Number(left).toFixed(2)}</Td><Td>{Number(right).toFixed(2)}</Td><Td>{delta(Number(right),Number(left),'')}</Td></Tr>)}</tbody></Table>:<p className="text-sm text-gray-500">Select two completed simulation runs to compare their operational outcomes.</p>}</div></Card>
    <Card><CardHeader title="Campaign history" subtitle="Queued and running campaigns survive page navigation and application restarts."/>{runs.length===0?<p className="p-8 text-sm text-gray-500 text-center">No campaign for this scenario.</p>:<Table><Thead><tr><Th>Type</Th><Th>Status</Th><Th>Progress</Th><Th>Started</Th><Th></Th></tr></Thead><tbody>{runs.map(run=><Tr key={run.id}><Td>{run.runType==='capacity_sweep'?'Capacity sweep':run.runType==='experiment'?'Experiment':'Simulation'}</Td><Td><span className="capitalize">{run.status}</span></Td><Td>{run.progress}%</Td><Td>{new Date(run.startedAt).toLocaleString()}</Td><Td><div className="flex gap-2">{run.status==='completed'&&run.result&&<button onClick={()=>onOpen(run)} className="text-xs text-blue-600">Open</button>}{(run.status==='queued'||run.status==='running')&&<><button onClick={()=>onTrack(run)} className="text-xs text-blue-600">Track</button><button onClick={()=>onCancel(run)} className="text-xs text-red-600">Cancel</button></>}</div></Td></Tr>)}</tbody></Table>}</Card>
  </div>;
}

function Results({analytic,result,baseline}:{analytic?:AnalyticResult;result?:SimulationResult;baseline?:SimulationResult}) {
  if(!analytic)return <Empty text="Run an analysis or simulation to see the results."/>;
  const metrics=result?.metrics;
  return <div className="space-y-5"><div className="grid sm:grid-cols-2 lg:grid-cols-5 gap-4"><KPI label="Expected cycle" value={`${analytic.cycleTimeMinutes.toFixed(1)} min`}/><KPI label="Processing" value={`${analytic.processingMinutes.toFixed(1)} min`}/><KPI label="Waiting" value={`${analytic.waitingMinutes.toFixed(1)} min`}/><KPI label="Cycle efficiency" value={`${(analytic.cycleTimeEfficiency*100).toFixed(1)}%`}/><KPI label="Cost / case" value={analytic.costPerExecution.toFixed(2)}/></div>{metrics&&<>{baseline&&<Card><CardHeader title="As-is vs to-be" subtitle="Change relative to the selected baseline; negative cycle time and cost are improvements."/><div className="p-6 pt-2 grid sm:grid-cols-3 gap-4"><KPI label="Mean-cycle change" value={delta(metrics.meanCycleMinutes,baseline.metrics.meanCycleMinutes,' min')}/><KPI label="Cost change" value={delta(metrics.meanCost,baseline.metrics.meanCost,'')}/><KPI label="Throughput change" value={delta(metrics.throughputPerHour,baseline.metrics.throughputPerHour,' / h')}/></div></Card>}<Card><CardHeader title="Simulation KPIs" subtitle={`${metrics.completed} completed cases; confidence intervals use independent replications.`}/><div className="p-6 pt-2 grid sm:grid-cols-2 lg:grid-cols-4 gap-4"><KPI label="Mean cycle" value={`${metrics.meanCycleMinutes.toFixed(1)} min`}/><KPI label="p95 cycle" value={`${metrics.p95CycleMinutes.toFixed(1)} min`}/><KPI label="Throughput" value={`${metrics.throughputPerHour.toFixed(2)} / h`}/><KPI label="Mean cost" value={metrics.meanCost.toFixed(2)}/></div></Card><Card><CardHeader title="Resource pressure" subtitle="Utilization above 85% is flagged as a capacity risk."/><Table><Thead><tr><Th>Resource</Th><Th>Capacity</Th><Th>Utilization</Th><Th>Mean queue</Th><Th>Maximum queue</Th></tr></Thead><tbody>{metrics.resources.map(r=><Tr key={r.resourceId}><Td>{r.name}</Td><Td>{r.capacity}</Td><Td><span className={r.utilization>=.85?'text-red-600 font-semibold':''}>{(r.utilization*100).toFixed(1)}%</span></Td><Td>{r.meanQueueLength.toFixed(2)}</Td><Td>{r.maximumQueueSize}</Td></Tr>)}</tbody></Table></Card></>}</div>;
}
function Issues({result,scenarioId}:{result?:SimulationResult;scenarioId:string}) { const queryClient=useQueryClient();const {data:persisted=[]}=useQuery({queryKey:['simulation-issues',scenarioId],queryFn:()=>listIssues(scenarioId),enabled:!!scenarioId});const shown=persisted.length?persisted:(result?.issues??[]);const [title,setTitle]=useState('');if(!result&&!scenarioId)return <Empty text="Run the simulation to generate evidence-based issues and redesign recommendations."/>;return <div className="space-y-5"><Card><CardHeader title="Issue register" subtitle="Detected evidence is persisted; status can be managed as the redesign progresses."/><div className="divide-y">{shown.length===0?<p className="p-6 text-sm text-gray-500">No configured threshold was exceeded.</p>:shown.map(i=><div key={i.id??i.code} className="p-5 flex gap-3"><AlertTriangle className={`w-5 h-5 flex-none ${i.severity==='high'?'text-red-500':'text-amber-500'}`}/><div className="flex-1"><div className="flex justify-between gap-3"><p className="font-medium text-sm">{i.title}</p>{i.id&&<select value={i.status??'open'} onChange={async e=>{await updateIssue({...i,status:e.target.value});await queryClient.invalidateQueries({queryKey:['simulation-issues',scenarioId]})}} className="table-input"><option value="open">Open</option><option value="accepted">Accepted</option><option value="resolved">Resolved</option><option value="dismissed">Dismissed</option></select>}</div><p className="text-sm text-gray-600 mt-1">{i.evidence}</p><p className="text-xs text-blue-700 mt-2">{i.suggestion}</p></div></div>)}</div>{scenarioId&&<form className="p-4 border-t flex gap-2" onSubmit={async e=>{e.preventDefault();if(!title.trim())return;await createIssue(scenarioId,{title,code:'MANUAL',evidence:'Added by analyst',category:'other',severity:'medium',suggestion:'Review during redesign',status:'open'});setTitle('');await queryClient.invalidateQueries({queryKey:['simulation-issues',scenarioId]})}}><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="Add an observed issue…" className="input"/><button className="px-3 py-2 bg-blue-600 text-white text-sm rounded-lg">Add</button></form>}</Card>{result&&<Card><CardHeader title="Redesign heuristics" subtitle="Candidates to test as a separate to-be scenario, not unverified prescriptions."/><div className="grid md:grid-cols-2 gap-4 p-6 pt-2">{result.recommendedDesign.map(r=><div key={r.title} className="border rounded-lg p-4"><span className="text-xs uppercase tracking-wide text-blue-600">{r.heuristic}</span><h3 className="font-semibold text-sm mt-1">{r.title}</h3><p className="text-sm text-gray-600 mt-2">{r.justification}</p></div>)}</div></Card>}</div>}
function delta(current:number,baseline:number,suffix:string){const value=current-baseline;return `${value>=0?'+':''}${value.toFixed(2)}${suffix}`}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="block"><span className="block text-xs font-medium text-gray-600 mb-1">{label}</span>{children}</label>}
function NumberField({label,value,onChange}:{label:string;value:number;onChange:(v:number)=>void}){return <Field label={label}><input type="number" value={value} onChange={e=>onChange(numeric(e.target.value))} className="input"/></Field>}
function KPI({label,value}:{label:string;value:string}){return <div className="bg-white border border-gray-200 rounded-xl p-4"><p className="text-xl font-bold text-gray-900">{value}</p><p className="text-xs text-gray-500 mt-1">{label}</p></div>}
function Empty({text}:{text:string}){return <Card className="p-12 text-center text-sm text-gray-500">{text}</Card>}
